import{_ as o,C as n,o as r,c as a,j as t,a as i,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"End the test","description":"End a stopped test where it stands, from the editor, the pause bar, Piwi Picker's Runs window, the desktop app or an agent: the call it stopped before never runs, and Playwright reports the test as skipped.","frontmatter":{"title":"End the test","description":"End a stopped test where it stands, from the editor, the pause bar, Piwi Picker's Runs window, the desktop app or an agent: the call it stopped before never runs, and Playwright reports the test as skipped.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/end-the-test.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/end-the-test.html"}],["meta",{"property":"og:title","content":"End the test | Piwi Dashboard"}],["meta",{"property":"og:description","content":"End a stopped test where it stands, from the editor, the pause bar, Piwi Picker's Runs window, the desktop app or an agent: the call it stopped before never runs, and Playwright reports the test as skipped."}]]},"headers":[],"relativePath":"features/end-the-test.md","filePath":"features/end-the-test.md","lastUpdated":1793207199000}`),l={name:"features/end-the-test.md"};function p(c,e,u,g,f,w){const s=n("Needs");return r(),a("div",null,[e[0]||(e[0]=t("h1",{id:"end-the-test",tabindex:"-1"},[i("End the test "),t("a",{class:"header-anchor",href:"#end-the-test","aria-label":'Permalink to "End the test"'},"​")],-1)),d(s,{fixtures:""}),e[1]||(e[1]=h('<p>At a stop, <strong>End the test</strong> ends the test there, as if it had called <code>test.skip()</code> at that line: the call it stopped before never runs, nor the rest of the test, and Playwright reports it as skipped, its <code>skip</code> annotation reading <code>Ended from Piwi</code>. The run goes on with its next test. Use it once you have seen what you stopped for, or recorded the steps you were missing, and the rest of the test has nothing to show you.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>It is offered at any stop but a failure, with a reporter newer than 0.62.0:</p><ul><li><strong>VS Code</strong>: <strong>End test</strong> on the stopped line&#39;s CodeLens and in its hover, the status bar beside <strong>Finish</strong>, and <strong>Piwi: End the test here, skipping the rest of it</strong> in the palette. It has no key: bind one in <strong>Preferences: Open Keyboard Shortcuts</strong> (search <code>piwi</code>).</li><li><strong>A JetBrains IDE</strong>: <strong>End Test</strong> in the stopped line&#39;s inlay and the arrow&#39;s menu, <strong>Tools → Piwi → End the Test</strong> and the status bar item&#39;s menu. Give it a key in <strong>Settings → Keymap</strong>.</li><li><strong>The <a href="./editor-breakpoints.html#pause-a-run">pause bar</a></strong>: <strong>End the test</strong>.</li><li><strong>Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a></strong> and the desktop app&#39;s <a href="./desktop-runs.html">Local runs tray</a>: <strong>End the test</strong>, beside <strong>Finish</strong>.</li><li><strong>An <a href="./agent-run-control.html">agent</a></strong>: <code>run_control</code> with <code>end</code>, answered as the test ends.</li></ul><h2 id="what-runs-and-what-does-not" tabindex="-1">What runs, and what does not <a class="header-anchor" href="#what-runs-and-what-does-not" aria-label="Permalink to &quot;What runs, and what does not&quot;">​</a></h2><ul><li><strong>At a locator call or an assertion</strong> (<code>click</code>, <code>fill</code>, <code>expect(locator).toBeVisible()</code>), the call is given up before it runs. At a <code>page.pause()</code>, nothing after it runs.</li><li><strong>At another call</strong> (a navigation, a key press on the page, <code>page.evaluate</code>), the call runs first: Piwi does not hold it. The test is skipped at its next locator call, or as its function ends, and the editor says so.</li><li><strong>At a failure</strong>, it is not offered: <strong>Resume</strong> lets the test end as it failed, and the failure is kept.</li><li><strong>In a <code>beforeEach</code> hook</strong>, it skips the test. <strong>In an <code>afterEach</code> hook or a fixture&#39;s teardown</strong>, the test&#39;s function already ended: it goes on as <strong>Resume</strong> does, keeping the test&#39;s result, and says so. Piwi never stops in a <code>beforeAll</code> or <code>afterAll</code> hook.</li><li><strong>After it</strong>, the test&#39;s <code>afterEach</code> hooks and its fixtures&#39; teardown run as after any skip, so its page closes as usual, with nothing of Piwi left in it.</li><li><strong>A retry</strong> is an attempt of its own. Playwright does not retry a skipped test; a failure you let end runs the next attempt, which stops at your breakpoints as the first did.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Playwright&#39;s calls alone.</strong> The test&#39;s own code between two calls, a loop or a helper, runs until its next call.</li><li><strong>One test.</strong> It ends the stopped worker&#39;s test; the run&#39;s other tests run. To end the run, <strong>Stop</strong> it (one Piwi started) or end it in its terminal.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the other controls at a stop.</li><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the pause bar.</li><li><a href="./runs-window.html">Runs window</a>: the same controls from Piwi Picker.</li><li><a href="./agent-run-control.html">Run control for agents</a>: <code>run_control</code> and the other tools.</li></ul>',10))])}const b=o(l,[["render",p]]);export{k as __pageData,b as default};
